// ---------------------------------------------------------------------------
// Avatar Spec for Providers (Matches cc-switch: Brand Logo or Initials)
// ---------------------------------------------------------------------------

#[derive(Clone, Debug)]
pub enum ProviderAvatarSpec {
    Svg {
        svg_data: &'static [u8],
        bg: Rgba,
        fg: Rgba,
    },
    Initials {
        text: String,
        bg: Rgba,
        fg: Rgba,
    },
}

fn extract_initials(name: &str) -> String {
    let trimmed = name.trim();
    if trimmed.is_empty() {
        return "?".to_string();
    }
    let words: Vec<&str> = trimmed.split_whitespace().collect();
    if words.len() >= 2 {
        let c1 = words[0].chars().next().unwrap_or('?');
        let c2 = words[1].chars().next().unwrap_or('?');
        format!("{}{}", c1.to_uppercase(), c2.to_uppercase())
    } else {
        let chars: Vec<char> = trimmed.chars().collect();
        if chars.len() >= 2 && chars[0].is_alphabetic() && !chars[0].is_ascii() {
            format!("{}{}", chars[0], chars[1])
        } else if let Some(c) = chars.first() {
            c.to_uppercase().to_string()
        } else {
            "?".to_string()
        }
    }
}

pub fn provider_avatar_spec(
    tool: aitoolplus_core::ToolId,
    name: &str,
    category: &str,
    theme: &Theme,
) -> ProviderAvatarSpec {
    let lower = name.to_lowercase();
    let is_official = category == "official" || lower.contains("official") || lower.contains("官方");

    if is_official {
        return match tool {
            aitoolplus_core::ToolId::ClaudeCode | aitoolplus_core::ToolId::ClaudeDesktop => {
                // In cc-switch, Claude Official prominently displays the Anthropic \A| logo
                ProviderAvatarSpec::Svg {
                    svg_data: ANTHROPIC_SVG,
                    bg: crate::rgba_const(0xd4915d20),
                    fg: crate::rgba_const(0xd4915dff),
                }
            }
            aitoolplus_core::ToolId::Codex => ProviderAvatarSpec::Svg {
                svg_data: OPENAI_SVG,
                bg: crate::rgba_const(0x10a37f22),
                fg: crate::rgba_const(0x10a37fff),
            },
            aitoolplus_core::ToolId::GeminiCli => ProviderAvatarSpec::Svg {
                svg_data: GEMINI_SVG,
                bg: crate::rgba_const(0x3186ff22),
                fg: crate::rgba_const(0x3186ffff),
            },
            aitoolplus_core::ToolId::Grok => {
                let (bg, fg) = if theme.is_dark {
                    (crate::rgba_const(0xffffff18), crate::rgba_const(0xf3f4f6ff))
                } else {
                    (crate::rgba_const(0x0000000c), crate::rgba_const(0x0f172aff))
                };
                ProviderAvatarSpec::Svg {
                    svg_data: GROK_SVG,
                    bg,
                    fg,
                }
            }
            aitoolplus_core::ToolId::Kimi => ProviderAvatarSpec::Svg {
                svg_data: KIMI_SVG,
                bg: crate::rgba_const(0x027aff22),
                fg: crate::rgba_const(0x027affff),
            },
            aitoolplus_core::ToolId::Pi => ProviderAvatarSpec::Svg {
                svg_data: PI_SVG,
                bg: crate::rgba_const(0xf59e0b20),
                fg: crate::rgba_const(0xf59e0bff),
            },
            aitoolplus_core::ToolId::OhMyPi => ProviderAvatarSpec::Svg {
                svg_data: OMP_SVG,
                bg: crate::rgba_const(0x8b5cf620),
                fg: crate::rgba_const(0x8b5cf6ff),
            },
            aitoolplus_core::ToolId::OpenCode => {
                let (bg, fg) = if theme.is_dark {
                    (crate::rgba_const(0xffffff18), crate::rgba_const(0xf3f4f6ff))
                } else {
                    (crate::rgba_const(0x0000000c), crate::rgba_const(0x0f172aff))
                };
                ProviderAvatarSpec::Svg {
                    svg_data: OPENCODE_SVG,
                    bg,
                    fg,
                }
            }
            aitoolplus_core::ToolId::OpenClaw => ProviderAvatarSpec::Svg {
                svg_data: CLAW_SVG,
                bg: crate::rgba_const(0xf43f5e20),
                fg: crate::rgba_const(0xf43f5eff),
            },
            aitoolplus_core::ToolId::Hermes => ProviderAvatarSpec::Svg {
                svg_data: HERMES_SVG,
                bg: crate::rgba_const(0x8b5cf620),
                fg: crate::rgba_const(0x8b5cf6ff),
            },
            aitoolplus_core::ToolId::Dsh => ProviderAvatarSpec::Svg {
                svg_data: DEEPSEEK_SVG,
                bg: crate::rgba_const(0x4d6bfe20),
                fg: crate::rgba_const(0x4d6bfeff),
            },
        };
    }

    // In cc-switch parity, Pi providers use the authentic Pi brand icon
    if tool == aitoolplus_core::ToolId::Pi {
        return ProviderAvatarSpec::Svg {
            svg_data: PI_SVG,
            bg: crate::rgba_const(0xf59e0b20),
            fg: crate::rgba_const(0xf59e0bff),
        };
    }

    if lower.contains("anthropic") {
        ProviderAvatarSpec::Svg {
            svg_data: ANTHROPIC_SVG,
            bg: crate::rgba_const(0xd4915d20),
            fg: crate::rgba_const(0xd4915dff),
        }
    } else if lower.contains("claude") {
        ProviderAvatarSpec::Svg {
            svg_data: CLAUDE_SVG,
            bg: crate::rgba_const(0xe07a5f22),
            fg: crate::rgba_const(0xd97757ff),
        }
    } else if lower.contains("deepseek") {
        ProviderAvatarSpec::Svg {
            svg_data: DEEPSEEK_SVG,
            bg: crate::rgba_const(0x4d6bfe22),
            fg: crate::rgba_const(0x4d6bfeff),
        }
    } else if lower.contains("openai") || lower.contains("codex") || lower.contains("chatgpt") {
        ProviderAvatarSpec::Svg {
            svg_data: OPENAI_SVG,
            bg: crate::rgba_const(0x10a37f22),
            fg: crate::rgba_const(0x10a37fff),
        }
    } else if lower.contains("gemini") || lower.contains("google") {
        ProviderAvatarSpec::Svg {
            svg_data: GEMINI_SVG,
            bg: crate::rgba_const(0x3186ff22),
            fg: crate::rgba_const(0x3186ffff),
        }
    } else if lower.contains("grok") || lower.contains("xai") {
        let (bg, fg) = if theme.is_dark {
            (crate::rgba_const(0xffffff18), crate::rgba_const(0xf3f4f6ff))
        } else {
            (crate::rgba_const(0x0000000c), crate::rgba_const(0x0f172aff))
        };
        ProviderAvatarSpec::Svg {
            svg_data: GROK_SVG,
            bg,
            fg,
        }
    } else if lower.contains("kimi") || lower.contains("moonshot") {
        ProviderAvatarSpec::Svg {
            svg_data: KIMI_SVG,
            bg: crate::rgba_const(0x027aff22),
            fg: crate::rgba_const(0x027affff),
        }
    } else if lower.contains("qwen") || lower.contains("ali") || lower.contains("bailian") || lower.contains("tongyi") || name.contains("千问") {
        ProviderAvatarSpec::Svg {
            svg_data: QWEN_SVG,
            bg: crate::rgba_const(0x6f69f720),
            fg: crate::rgba_const(0x6f69f7ff),
        }
    } else if lower.contains("zhipu") || lower.contains("glm") || name.contains("智谱") {
        ProviderAvatarSpec::Svg {
            svg_data: ZHIPU_SVG,
            bg: crate::rgba_const(0x3859ff20),
            fg: crate::rgba_const(0x3859ffff),
        }
    } else if lower.contains("minimax") {
        ProviderAvatarSpec::Svg {
            svg_data: MINIMAX_SVG,
            bg: crate::rgba_const(0xe2167e20),
            fg: crate::rgba_const(0xfe603cff),
        }
    } else if lower.contains("doubao") || lower.contains("bytedance") || lower.contains("volc") || name.contains("豆包") || name.contains("火山") {
        ProviderAvatarSpec::Svg {
            svg_data: DOUBAO_SVG,
            bg: crate::rgba_const(0x1e37fc20),
            fg: crate::rgba_const(0x37e1beff),
        }
    } else if lower.contains("silicon") || lower.contains("siliconflow") || name.contains("硅基") {
        ProviderAvatarSpec::Svg {
            svg_data: SILICONFLOW_SVG,
            bg: crate::rgba_const(0x6e29f620),
            fg: crate::rgba_const(0x6e29f6ff),
        }
    } else if lower.contains("openrouter") {
        ProviderAvatarSpec::Svg {
            svg_data: OPENROUTER_SVG,
            bg: crate::rgba_const(0x3b82f620),
            fg: crate::rgba_const(0x3b82f6ff),
        }
    } else if lower.contains("copilot") || lower.contains("github") {
        let (bg, fg) = if theme.is_dark {
            (crate::rgba_const(0xffffff18), crate::rgba_const(0xf3f4f6ff))
        } else {
            (crate::rgba_const(0x0000000c), crate::rgba_const(0x0f172aff))
        };
        ProviderAvatarSpec::Svg {
            svg_data: GITHUB_SVG,
            bg,
            fg,
        }
    } else if lower.contains("pi") {
        ProviderAvatarSpec::Svg {
            svg_data: PI_SVG,
            bg: crate::rgba_const(0xf59e0b20),
            fg: crate::rgba_const(0xf59e0bff),
        }
    } else if lower.contains("opencode") && tool != aitoolplus_core::ToolId::OpenCode {
        let (bg, fg) = if theme.is_dark {
            (crate::rgba_const(0xffffff18), crate::rgba_const(0xf3f4f6ff))
        } else {
            (crate::rgba_const(0x0000000c), crate::rgba_const(0x0f172aff))
        };
        ProviderAvatarSpec::Svg {
            svg_data: OPENCODE_SVG,
            bg,
            fg,
        }
    } else if lower.contains("openclaw") && tool != aitoolplus_core::ToolId::OpenClaw {
        ProviderAvatarSpec::Svg {
            svg_data: CLAW_SVG,
            bg: crate::rgba_const(0xf43f5e20),
            fg: crate::rgba_const(0xf43f5eff),
        }
    } else {
        // Fallback: Exactly like cc-switch, display the 1-2 character initials of the provider name!
        let initials = extract_initials(name);
        let (bg, fg) = if theme.is_dark {
            (crate::rgba_const(0xffffff0e), crate::rgba_const(0xffffffcc))
        } else {
            (crate::rgba_const(0x0000000a), crate::rgba_const(0x0f172acc))
        };
        ProviderAvatarSpec::Initials {
            text: initials,
            bg,
            fg,
        }
    }
}

pub fn tool_icon(tool: aitoolplus_core::ToolId) -> &'static [u8] {
    match tool {
        aitoolplus_core::ToolId::ClaudeCode | aitoolplus_core::ToolId::ClaudeDesktop => CLAUDE_SVG,
        aitoolplus_core::ToolId::Codex => OPENAI_SVG,
        aitoolplus_core::ToolId::GeminiCli => GEMINI_SVG,
        aitoolplus_core::ToolId::Grok => GROK_SVG,
        aitoolplus_core::ToolId::Kimi => KIMI_SVG,
        aitoolplus_core::ToolId::OpenCode => OPENCODE_SVG,
        aitoolplus_core::ToolId::OpenClaw => CLAW_SVG,
        aitoolplus_core::ToolId::Hermes => HERMES_SVG,
        aitoolplus_core::ToolId::Pi => PI_SVG,
        aitoolplus_core::ToolId::OhMyPi => OMP_SVG,
        aitoolplus_core::ToolId::Dsh => DEEPSEEK_SVG,
    }
}
